/**
 * API schema compatibility: validates the TypeScript contract shapes
 * against fixtures captured from the REAL FastAPI app (generated by
 * `frontend/scripts/dump_api_fixtures.py` with the same code path as
 * production — scripted fakes, no network, no live model calls).
 *
 * If the backend evolves, regenerate the fixtures; a mismatch here
 * means the UI types no longer describe reality.
 */
import { describe, expect, it } from "vitest";
import config from "./fixtures/backend/config.json";
import error404 from "./fixtures/backend/error_404.json";
import errorResume404 from "./fixtures/backend/error_404_resume.json";
import health from "./fixtures/backend/health.json";
import models from "./fixtures/backend/models.json";
import runAccepted from "./fixtures/backend/run_accepted.json";
import runDetail from "./fixtures/backend/run_detail_completed.json";
import sessionCreated from "./fixtures/backend/session_created.json";
import sessionDetail from "./fixtures/backend/session_detail.json";
import sessionRenamed from "./fixtures/backend/session_renamed.json";
import sessionsList from "./fixtures/backend/sessions_list.json";

const RUN_STATUSES = [
  "queued",
  "running",
  "cancelling",
  "completed",
  "failed",
  "cancelled",
  "interrupted",
];

function expectKeys(object: object, keys: string[]): void {
  for (const key of keys) {
    expect(object).toHaveProperty(key);
  }
}

describe("FastAPI schema compatibility (real captured fixtures)", () => {
  it("GET /api/config matches ConfigOut", () => {
    expectKeys(config, [
      "provider",
      "model",
      "thinking_level",
      "max_total_execution_seconds",
      "max_research_iterations",
      "max_tool_calls_per_research",
      "min_findings",
      "min_retrieved_sources",
      "max_concurrent_runs",
      "resume_enabled",
    ]);
    expect(typeof config.provider).toBe("string");
    expect(typeof config.max_total_execution_seconds).toBe("number");
    expect(typeof config.resume_enabled).toBe("boolean");
  });

  it("GET /api/health matches HealthOut", () => {
    expectKeys(health, ["ok"]);
    expect(typeof health.ok).toBe("boolean");
  });

  it("POST /api/sessions matches SessionOut", () => {
    expectKeys(sessionCreated, ["id", "title", "created_at", "updated_at", "run_count"]);
    expect(typeof sessionCreated.title).toBe("string");
    expect(sessionCreated.title.length).toBeLessThanOrEqual(120);
  });

  it("POST /api/sessions/{id}/runs matches RunAcceptedOut", () => {
    expectKeys(runAccepted, ["run_id", "status", "events_url"]);
    expect(RUN_STATUSES).toContain(runAccepted.status);
  });

  it("GET /api/sessions matches SessionOut[] with run counts", () => {
    expect(Array.isArray(sessionsList)).toBe(true);
    expectKeys(sessionsList[0] as object, ["id", "title", "created_at", "updated_at"]);
  });

  it("GET /api/sessions/{id} matches SessionDetailOut (ordered runs)", () => {
    expectKeys(sessionDetail, ["session", "runs"]);
    expectKeys(sessionDetail.session as object, [
      "id",
      "title",
      "created_at",
      "updated_at",
    ]);
    expect(sessionDetail.runs.length).toBeGreaterThan(0);
    expectKeys(sessionDetail.runs[0] as object, [
      "id",
      "session_id",
      "question",
      "status",
      "has_answer",
      "created_at",
    ]);
    expect(RUN_STATUSES).toContain((sessionDetail.runs[0] as { status: string }).status);
  });

  it("GET /api/runs/{id} matches RunDetailOut incl. sources + diagnostics", () => {
    expectKeys(runDetail, [
      "id",
      "session_id",
      "question",
      "status",
      "answer",
      "review_status",
      "outcome_status",
      "outcome_warnings",
      "error_category",
      "iterations",
      "tokens_in",
      "tokens_out",
      "estimated_cost_usd",
      "total_execution_seconds",
      "sources",
      "diagnostics",
      "created_at",
      "started_at",
      "finished_at",
      "events_url",
      // 4E.1/4E.3: settings frozen at run creation
      "research_depth",
      "evidence_policy",
      "model_id",
      "thinking_level",
    ]);
    expect(RUN_STATUSES).toContain(runDetail.status);
    // this fixture run used the configured defaults (frozen, not null)
    expect(runDetail.model_id).toBe("gemini-3.8-flash");
    expect(runDetail.thinking_level).toBe("medium");
    expect(runDetail.research_depth).toBe("standard");
    expect(runDetail.evidence_policy).toBe("balanced");

    // sources carry the per-run citation contract
    const source = runDetail.sources[0] as Record<string, unknown>;
    expectKeys(source, ["sid", "url", "host", "evidence", "position"]);
    expect(["retrieved", "snippet"]).toContain(source.evidence);

    // diagnostics block (content-free) matches the snapshot contract
    const diagnostics = runDetail.diagnostics as Record<string, any>;
    expectKeys(diagnostics, [
      "run_id",
      "started_at",
      "finished_at",
      "total_execution_seconds",
      "outcome",
      "deadline",
      "totals",
      "token_usage",
      "tokens_by_node",
      "model_calls",
      "tool_calls",
      "nodes",
      "counts",
      "security",
      "quality",
      "retries",
    ]);
    expectKeys(diagnostics.outcome, ["status", "warnings"]);
    expectKeys(diagnostics.totals, [
      "input_tokens",
      "output_tokens",
      "model_calls",
      "tool_calls",
      "retries",
    ]);
    expectKeys(diagnostics.token_usage, [
      "input_tokens",
      "output_tokens",
      "provider_reported_calls",
      "estimated_calls",
      "unavailable_calls",
      "coverage_ratio",
      "sources",
      // 4E.3: thinking tokens are provider-reported (null = absent)
      "thinking_tokens",
      "thinking_reported_calls",
    ]);
    expect(diagnostics.token_usage.thinking_tokens).toBeNull();
    // 4E.3: the frozen run configuration is stamped on the snapshot
    expectKeys(diagnostics.run_config, [
      "model_id",
      "thinking_level",
      "research_depth",
      "evidence_policy",
    ]);
    expect(diagnostics.run_config.model_id).toBe("gemini-3.8-flash");
    expect(diagnostics.run_config.thinking_level).toBe("medium");
    expectKeys(diagnostics.counts, [
      "searches",
      "fetches",
      "failed_searches",
      "failed_fetches",
      "failed_tool_calls",
      "tool_error_categories",
    ]);
    expectKeys(diagnostics.security, [
      "injection_signals",
      "tool_refusals",
      "answer_redactions",
    ]);
    expectKeys(diagnostics.quality, [
      "citations_ok",
      "coverage_ok",
      "official_status",
      "review_status",
      "missing_topics",
      "retrieved_sources",
      "snippet_sources",
    ]);
    // the UI types allow null iterations — the backend actually sends them
    expect(diagnostics.model_calls[0]).toHaveProperty("iteration");
    expect(diagnostics.model_calls[0]).toHaveProperty("thinking_tokens");
    expect(diagnostics.nodes[0]).toHaveProperty("iteration");
    // tokens_by_node is a nested object, not a bare number
    const firstNode = diagnostics.tokens_by_node[Object.keys(diagnostics.tokens_by_node)[0]];
    expectKeys(firstNode, ["calls", "input_tokens", "output_tokens", "prompt_chars"]);
  });

  it("GET /api/models matches the catalogue contract (4E.3)", () => {
    expectKeys(models, [
      "default_model_id",
      "default_thinking_level",
      "discovery",
      "models",
      "unregistered",
    ]);
    // discovery is opt-in: off by default, nothing was fetched
    expect(models.discovery.status).toBe("disabled");
    expect(models.discovery.checked_at).toBeNull();
    expect(typeof models.default_model_id).toBe("string");
    expect(models.models.length).toBeGreaterThan(0);
    const entry = models.models[0] as Record<string, any>;
    expectKeys(entry, [
      "model_id",
      "display_name",
      "family",
      "status",
      "free_tier",
      "selectable",
      "thinking",
      "availability",
      "verified_on",
      "docs_url",
    ]);
    expect(typeof entry.selectable).toBe("boolean");
    // the configured default is selectable and listed first
    expect(models.models[0].model_id).toBe(models.default_model_id);
    expect(entry.selectable).toBe(true);
    // thinking capabilities drive the capability-aware selector
    expect(["level", "budget", "none"]).toContain(entry.thinking.control);
    expect(Array.isArray(entry.thinking.levels)).toBe(true);
    // excluded models always state why
    for (const model of models.models as Record<string, any>[]) {
      if (!model.selectable) expect(model.exclusion_reason).toBeTruthy();
    }
  });

  it("PATCH /api/sessions/{id} matches SessionOut (4E.3 rename)", () => {
    expectKeys(sessionRenamed, ["id", "title", "created_at", "updated_at"]);
    expect(sessionRenamed.title).toBe("Renamed fixture session");
    // renaming is metadata editing: it never rewrites created_at
    expect(sessionRenamed.created_at).toBe(sessionCreated.created_at);
  });

  it("error bodies match the fixed {error:{category,message}} contract", () => {
    expectKeys(error404, ["error"]);
    expectKeys(error404.error, ["category", "message"]);
    expect(typeof error404.error.category).toBe("string");
    expect(typeof error404.error.message).toBe("string");
    expectKeys(errorResume404.error, ["category", "message"]);
  });
});
